async countAgents(): Promise<number> {
  return this.withDatabase(async () => {
    try {
      const result = await this.db.select({ count: count() }).from(agentTable);

      const result0 = result[0];
      return result0?.count || 0;
    } catch (error) {
      logger.error(
        {
          src: "plugin:sql",
          error: error instanceof Error ? error.message : String(error),
        },
        "Failed to count agents"
      );
      return 0;
    }
  });
}

async createEntities(entities: Entity[]): Promise<UUID[]> {
  return this.withDatabase(async () => {
    // Pre-assign IDs so duplicates (by id) can be reported as
    // already-created → success (idempotent create; see ON CONFLICT below).
    const normalizedEntities = entities.map((entity) => {
      const { names, metadata, ...normalizedEntity } = entity as Entity & {
        names?: unknown;
        metadata?: Metadata;
      };
      const id = (entity.id || v4()) as UUID;
      return {
        ...normalizedEntity,
        id,
        agentId: this.agentId,
        names: this.normalizeEntityNames(names),
        metadata: metadata || {},
      };
    });

    try {
      // ON CONFLICT DO NOTHING keeps the create idempotent per row: rows
      // whose id already exists are skipped (never clobbered — that's
      // upsertEntities' job) while the rest of the batch still lands. The
      // previous catch-on-duplicate approach rolled back the whole batch and
      // then claimed success for entities that were never written. Both of
      // entityTable's unique constraints (PK id, unique(id, agentId)) are
      // id-based, so any conflict here is a duplicate id.
      const inserted = await this.db
        .insert(entityTable)
        .values(normalizedEntities)
        .onConflictDoNothing()
        .returning();
      if (inserted.length < normalizedEntities.length) {
        logger.warn(
          {
            src: "plugin:sql",
            requested: normalizedEntities.length,
            inserted: inserted.length,
          },
          "Some entities already existed; treating them as created"
        );
      }
      return normalizedEntities.map((entity) => entity.id as UUID);
    } catch (error) {
      logger.error(
        {
          src: "plugin:sql",
          entityId: entities[0]?.id,
          error: error instanceof Error ? error.message : String(error),
        },
        "Failed to create entities"
      );
      return [];
    }
  });
}

export function readStoredMediaBytes(fileName: string): Buffer | null {
  const filePath = path.join(mediaDir(), fileName);
  if (path.dirname(filePath) !== mediaDir()) return null;
  try {
    return fs.existsSync(filePath) ? fs.readFileSync(filePath) : null;
  } catch {
    return null;
  }
}

export function writeStoredMediaFile(fileName: string, bytes: Buffer): boolean {
  const filePath = path.join(mediaDir(), fileName);
  if (path.dirname(filePath) !== mediaDir()) return false;
  try {
    fs.mkdirSync(mediaDir(), { recursive: true });
    if (!fs.existsSync(filePath)) fs.writeFileSync(filePath, bytes);
    return true;
  } catch {
    return false;
  }
}

function parseObjectCandidate<T extends object>(candidate: string): T | null {
	try {
		const parsed = JSON.parse(candidate);
		if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
			return parsed as T;
		}
	} catch {
		const objectText = extractJsonObjects(candidate)[0];
		if (!objectText) return null;
		try {
			const parsed = JSON.parse(objectText);
			if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
				return parsed as T;
			}
		} catch {
			return null;
		}
	}
	return null;
}

export function parseJsonObject<T extends object>(raw: string): T | null {
	const trimmed = raw.trim();
	if (!trimmed) {
		return null;
	}

	const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
	const candidate = fenced?.[1] ?? trimmed;

	const parsedCandidate =
		parseObjectCandidate<T>(candidate) ??
		parseObjectCandidate<T>(repairJsonStringEscapes(candidate));
	if (parsedCandidate) {
		return parsedCandidate;
	}

	const repairedCandidate = repairJsonStringEscapes(candidate);
	const objectText =
		extractJsonObjects(candidate)[0] ??
		(repairedCandidate === candidate
			? null
			: extractJsonObjects(repairedCandidate)[0]);
	if (!objectText) return null;

	return (
		parseObjectCandidate<T>(objectText) ??
		parseObjectCandidate<T>(repairJsonStringEscapes(objectText))
	);
}

export async function retry(
  fetchFn: () => Promise<Response>,
  options: {
    config: RetryConfig;
    statusCodes: string[];
  },
): Promise<Response> {
  switch (options.config.strategy) {
    case "backoff":
      return retryBackoff(
        wrapFetcher(fetchFn, {
          statusCodes: options.statusCodes,
          retryConnectionErrors: !!options.config.retryConnectionErrors,
        }),
        options.config.backoff ?? defaultBackoff,
      );
    default:
      return await fetchFn();
  }
}

function wrapFetcher(
  fn: () => Promise<Response>,
  options: {
    statusCodes: string[];
    retryConnectionErrors: boolean;
  },
): () => Promise<Response> {
  return async () => {
    try {
      const res = await fn();
      if (isRetryableResponse(res, options.statusCodes)) {
        throw new TemporaryError(
          "Response failed with retryable status code",
          res,
        );
      }

      return res;
    } catch (err: unknown) {
      if (err instanceof TemporaryError) {
        throw err;
      }

      if (
        options.retryConnectionErrors &&
        (isTimeoutError(err) || isConnectionError(err))
      ) {
        throw err;
      }

      throw new PermanentError("Permanent error", { cause: err });
    }
  };
}

async function retryBackoff(
  fn: () => Promise<Response>,
  strategy: BackoffStrategy,
): Promise<Response> {
  const { maxElapsedTime, initialInterval, exponent, maxInterval } = strategy;

  const start = Date.now();
  let x = 0;

  while (true) {
    try {
      const res = await fn();
      return res;
    } catch (err: unknown) {
      if (err instanceof PermanentError) {
        throw err.cause;
      }
      const elapsed = Date.now() - start;
      if (elapsed > maxElapsedTime) {
        if (err instanceof TemporaryError) {
          return err.response;
        }

        throw err;
      }

      let retryInterval = 0;
      if (err instanceof TemporaryError) {
        retryInterval = retryIntervalFromResponse(err.response);
      }

      if (retryInterval <= 0) {
        retryInterval =
          initialInterval * Math.pow(x, exponent) + Math.random() * 1000;
      }

      const d = Math.min(retryInterval, maxInterval);

      await delay(d);
      x++;
    }
  }
}

function retryIntervalFromResponse(res: Response): number {
  const retryVal = res.headers.get("retry-after") || "";
  if (!retryVal) {
    return 0;
  }

  const parsedNumber = Number(retryVal);
  if (Number.isInteger(parsedNumber)) {
    return parsedNumber * 1000;
  }

  const parsedDate = Date.parse(retryVal);
  if (Number.isInteger(parsedDate)) {
    const deltaMS = parsedDate - Date.now();
    return deltaMS > 0 ? Math.ceil(deltaMS) : 0;
  }

  return 0;
}

export let getValue = <T extends object>(value: T): T => {
	const proxyDraft = getProxyDraft(value)
	// Use the copy only if the draft was actually modified. An unmodified
	// draft can still have a copy_ (e.g. the get trap caches child drafts
	// there), and using it would both break structural sharing and leak
	// soon-to-be-revoked child drafts into the result.
	return proxyDraft ? getFinalValue(proxyDraft) : value
}
